class Solution {
public:
    vector<int> groupStrings(vector<string>& words) {
        int n = words.size();
        vector<int> parent(n), sz(n, 1);
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> find = [&](int i) {
            return parent[i] == i ? i : parent[i] = find(parent[i]);
        };
        auto unite = [&](int i, int j) {
            int pi = find(i), pj = find(j);
            if (pi != pj) {
                parent[pi] = pj;
                sz[pj] += sz[pi];
            }
        };
        unordered_map<int, int> maskToId;
        unordered_map<int, int> delToId;
        for (int idx = 0; idx < n; idx++) {
            int m = 0;
            for (char ch : words[idx]) m |= (1 << (ch - 'a'));
            if (maskToId.count(m)) {
                unite(idx, maskToId[m]);
            } else {
                maskToId[m] = idx;
            }
            for (int i = 0; i < 26; i++) {
                if ((m >> i) & 1) {
                    int sub = m ^ (1 << i);
                    if (maskToId.count(sub)) unite(idx, maskToId[sub]);
                    if (delToId.count(sub)) unite(idx, delToId[sub]);
                    else delToId[sub] = idx;
                }
            }
        }
        int groups = 0, maxSize = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) {
                groups++;
                maxSize = max(maxSize, sz[i]);
            }
        }
        return {groups, maxSize};
    }
};

class Solution {
    int[] parent;
    int[] sz;
    int find(int i) {
        return parent[i] == i ? i : (parent[i] = find(parent[i]));
    }
    void union(int i, int j) {
        int pi = find(i), pj = find(j);
        if (pi != pj) {
            parent[pi] = pj;
            sz[pj] += sz[pi];
        }
    }
    public int[] groupStrings(String[] words) {
        int n = words.length;
        parent = new int[n];
        sz = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            sz[i] = 1;
        }
        Map<Integer, Integer> maskToId = new HashMap<>();
        Map<Integer, Integer> delToId = new HashMap<>();
        for (int idx = 0; idx < n; idx++) {
            int m = 0;
            for (char ch : words[idx].toCharArray()) m |= (1 << (ch - 'a'));
            if (maskToId.containsKey(m)) {
                union(idx, maskToId.get(m));
            } else {
                maskToId.put(m, idx);
            }
            for (int i = 0; i < 26; i++) {
                if (((m >> i) & 1) == 1) {
                    int sub = m ^ (1 << i);
                    if (maskToId.containsKey(sub)) union(idx, maskToId.get(sub));
                    if (delToId.containsKey(sub)) union(idx, delToId.get(sub));
                    else delToId.put(sub, idx);
                }
            }
        }
        int groups = 0, maxSize = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) {
                groups++;
                maxSize = Math.max(maxSize, sz[i]);
            }
        }
        return new int[]{groups, maxSize};
    }
}

var groupStrings = function(words) {
    const n = words.length;
    const parent = new Int32Array(n);
    const sz = new Int32Array(n).fill(1);
    for (let i = 0; i < n; i++) parent[i] = i;
    function find(i) {
        return parent[i] === i ? i : (parent[i] = find(parent[i]));
    }
    function union(i, j) {
        const pi = find(i), pj = find(j);
        if (pi !== pj) {
            parent[pi] = pj;
            sz[pj] += sz[pi];
        }
    }
    const maskToId = new Map();
    const delToId = new Map();
    for (let idx = 0; idx < n; idx++) {
        let m = 0;
        const w = words[idx];
        for (let i = 0; i < w.length; i++) m |= (1 << (w.charCodeAt(i) - 97));
        if (maskToId.has(m)) {
            union(idx, maskToId.get(m));
        } else {
            maskToId.set(m, idx);
        }
        for (let i = 0; i < 26; i++) {
            if ((m >> i) & 1) {
                const sub = m ^ (1 << i);
                if (maskToId.has(sub)) union(idx, maskToId.get(sub));
                if (delToId.has(sub)) union(idx, delToId.get(sub));
                else delToId.set(sub, idx);
            }
        }
    }
    let groups = 0, maxSize = 0;
    for (let i = 0; i < n; i++) {
        if (parent[i] === i) {
            groups++;
            if (sz[i] > maxSize) maxSize = sz[i];
        }
    }
    return [groups, maxSize];
};
